--
-- Table structure for table `iot_collect_data`
--

DROP TABLE IF EXISTS `iot_collect_data`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `iot_collect_data` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `cid` bigint DEFAULT NULL COMMENT '任务执行标识',
  `uid` bigint DEFAULT NULL COMMENT '设备uid',
  `puid` bigint DEFAULT NULL COMMENT '父设备uid',
  `field_id` bigint NOT NULL COMMENT '信号id',
  `field` varchar(36) DEFAULT NULL COMMENT '数据类型',
  `task_id` bigint DEFAULT NULL COMMENT '任务id',
  `address` varchar(128) DEFAULT NULL COMMENT '信号地址',
  `value` varchar(256) DEFAULT NULL COMMENT '值',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '采集状态',
  `reason` varchar(64) NOT NULL DEFAULT '' COMMENT '错误说明',
  `collect_mode` enum('model','signal') DEFAULT NULL COMMENT '采集方式',
  `collect_time` datetime NOT NULL COMMENT '采集时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `product_code` varchar(64) DEFAULT NULL COMMENT '产品编码',
  `grade` enum('fatal','urgent','warn','notice','indicator','normal','status') DEFAULT NULL COMMENT '告警等级',
  `indicator` varchar(32) DEFAULT NULL COMMENT '指标',
  `protocol_code` varchar(64) DEFAULT NULL COMMENT '协议编码',
  `device_group_Id` bigint DEFAULT NULL COMMENT '设备组',
  `device_name` varchar(64) DEFAULT NULL COMMENT '设备名称',
  `device_sn` varchar(64) DEFAULT NULL COMMENT '设备编号',
  `field_name` varchar(64) DEFAULT NULL COMMENT '字段名称',
  PRIMARY KEY (`id`),
  KEY `iot_collect_data_cid_index` (`cid` DESC),
  KEY `iot_collect_data_collect_time_index` (`collect_time` DESC),
  KEY `iot_collect_data_uid_index` (`uid` DESC),
  KEY `iot_collect_data_field_id_index` (`field_id`)
) ENGINE=InnoDB AUTO_INCREMENT=209 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='采集到的数据';
/*!40101 SET character_set_client = @saved_cs_client */;

