CREATE TABLE `iot_device` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `uid` bigint NOT NULL COMMENT '设备唯一的uid',
  `pid` bigint DEFAULT NULL COMMENT '父设备(用于网关子设备产品)',
  `name` varchar(64) NOT NULL COMMENT '设备名称',
  `lon` varchar(24) DEFAULT NULL COMMENT '经度',
  `lat` varchar(24) DEFAULT NULL COMMENT '纬度',
  `ip` varchar(32) DEFAULT NULL COMMENT '设备ip',
  `port` int DEFAULT NULL COMMENT '设备端口',
  `product_id` bigint NOT NULL COMMENT '设备产品',
  `status` enum('online','offline') NOT NULL DEFAULT 'offline' COMMENT '设备状态',
  `address` varchar(64) DEFAULT NULL COMMENT '地址',
  `extend` json DEFAULT NULL,
  `account` varchar(64) DEFAULT NULL COMMENT '账号',
  `password` varchar(64) DEFAULT NULL COMMENT '密码',
  `device_sn` varchar(64) NOT NULL COMMENT '设备编号',
  `config` json DEFAULT NULL COMMENT '设备配置',
  `switch_time` timestamp NULL DEFAULT NULL COMMENT '设备状态切换时间',
  `update_time` timestamp NULL DEFAULT NULL COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `device_group_id` bigint DEFAULT NULL COMMENT '所属组',
  PRIMARY KEY (`id`),
  UNIQUE KEY `iot_device_uid_uindex` (`uid`),
  KEY `iot_device_create_time_index` (`create_time` DESC),
  KEY `iot_device_device_sn_index` (`device_sn`)
) ENGINE=InnoDB AUTO_INCREMENT=256 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='设备表';
