--
-- Table structure for table `iot_model_api_config`
--

DROP TABLE IF EXISTS `iot_model_api_config`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `iot_model_api_config` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `sort` int DEFAULT NULL COMMENT '排序',
  `api_code` varchar(32) NOT NULL COMMENT 'api接口码',
  `attr_field` varchar(32) DEFAULT NULL COMMENT '物模型属性',
  `data_type` char(16) DEFAULT NULL COMMENT '数据类型',
  `attr_name` varchar(64) DEFAULT NULL COMMENT '配置名称',
  `field_type` char(16) DEFAULT 'field' COMMENT '字段类型(状态、属性)',
  `product_id` bigint DEFAULT NULL COMMENT '所属产品',
  `value` varchar(512) DEFAULT NULL COMMENT '配置值',
  `remark` varchar(128) DEFAULT NULL COMMENT '备注',
  `model_attr_id` bigint DEFAULT NULL COMMENT '模型属性id',
  `protocol_data_type` char(16) DEFAULT NULL COMMENT '协议数据类型',
  `protocol_attr_field` varchar(32) DEFAULT NULL COMMENT '协议属性字段',
  `protocol_attr_name` varchar(32) DEFAULT NULL COMMENT '协议属性名称',
  `direction` enum('UP','DOWN') DEFAULT NULL COMMENT '方向(上行UP, 下行DOWN)',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `iot_model_api_config_api_code_index` (`api_code`),
  KEY `iot_model_api_config_model_attr_id_index` (`model_attr_id`),
  KEY `iot_model_api_config_product_id_index` (`product_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2063 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='物模型接口配置';
/*!40101 SET character_set_client = @saved_cs_client */;

