--
-- Table structure for table `iot_model_attr`
--

DROP TABLE IF EXISTS `iot_model_attr`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `iot_model_attr` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `product_id` bigint NOT NULL COMMENT '所属产品',
  `field` varchar(36) NOT NULL COMMENT '属性代码',
  `name` varchar(36) NOT NULL COMMENT '属性名称',
  `sort` int DEFAULT '0' COMMENT '排序',
  `data_type` char(16) DEFAULT NULL COMMENT '数据类型',
  `unit` varchar(36) DEFAULT NULL COMMENT '单位',
  `config` json DEFAULT NULL COMMENT '配置',
  `accuracy` tinyint DEFAULT NULL COMMENT '精度',
  `remark` varchar(256) DEFAULT NULL COMMENT '描述',
  `origin` enum('Protocol','Model') DEFAULT 'Model' COMMENT '属性来源',
  `attr_type` char(16) DEFAULT NULL COMMENT '功能类型(读、写)',
  `real_type` char(16) DEFAULT NULL COMMENT '实际类型',
  `enumerate` tinyint(1) DEFAULT '0' COMMENT '是否枚举',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `default_value` varchar(512) DEFAULT NULL,
  `ctrl_status` tinyint(1) DEFAULT '0' COMMENT '控制状态',
  `gain` smallint DEFAULT NULL COMMENT '数据增益',
  `resolver` varchar(36) DEFAULT 'DEFAULT' COMMENT '数据解析器',
  `script` varchar(512) DEFAULT NULL COMMENT '自定义解析脚本',
  PRIMARY KEY (`id`),
  KEY `iot_model_attr_product_sn_index` (`product_id`),
  KEY `iot_model_attr_sort_index` (`sort`)
) ENGINE=InnoDB AUTO_INCREMENT=687 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='物模型属性';
/*!40101 SET character_set_client = @saved_cs_client */;

